/// <summary>
/// <c>TelemetryDataManagementImport</c> class log monitoring and telemetry custom events/metrics
/// </summary>
internal final class ISMTelemetryDataManagementImport extends ISMTelemetryBase
{
    private DMFDefinitionGroupExecutionHistory  dmfDefinitionGroupExecutionHistory;
    private TransDateTime                       executionStartTime;
    private TransDateTime                       executionEndTime;
}

Method.Source:
void new(TransDateTime _operationStart, TransDateTime _operationEnd,DMFDefinitionGroupExecutionHistory _dmfDefinitionGroupExecutionHistory)
{
    super();
    dmfDefinitionGroupExecutionHistory = _dmfDefinitionGroupExecutionHistory;
    executionStartTime = _operationStart;
    executionEndTime = _operationEnd;
}

/// <summary>
/// populate telemetry entries to a map
/// </summary>
protected void postpopulateProperties()
{
    // We don't have to call the SetElapsedMilliSeconds() because we are getting the execution time from the table entry
    // this.setElapsedMilliseconds();
    this.addBaseProperty(ISMTelemetryProperties::ElapsedMilliseconds, int642Str(DateTimeUtil::getDifference(executionEndTime, executionStartTime)));
    this.addBaseProperty(ISMTelemetryProperties::DefinitionGroup, dmfDefinitionGroupExecutionHistory.DefinitionGroup);
    this.addBaseProperty(ISMTelemetryProperties::Entity, dmfDefinitionGroupExecutionHistory.Entity);
    this.addBaseProperty(ISMTelemetryProperties::ExecutionId,dmfDefinitionGroupExecutionHistory.ExecutionId);
    this.addBaseProperty(ISMTelemetryProperties::NoOfRecords, int2Str(dmfDefinitionGroupExecutionHistory.NoOfRecords));
    this.addBaseProperty(ISMTelemetryProperties::NumOfTargetNew,int2Str(dmfDefinitionGroupExecutionHistory.NumOfTargetNew));
    this.addBaseProperty(ISMTelemetryProperties::NumOfTargetUpdated, int2Str(dmfDefinitionGroupExecutionHistory.NumOfTargetUpdated));
    this.addBaseProperty(ISMTelemetryProperties::FILEPATH, dmfDefinitionGroupExecutionHistory.FILEPATH);
    this.addBaseProperty(ISMTelemetryProperties::FILETYPE, int2Str(dmfDefinitionGroupExecutionHistory.FILETYPE));
    this.addBaseProperty(ISMTelemetryProperties::NUMOFSTAGINGNEW, int2Str(dmfDefinitionGroupExecutionHistory.NUMOFSTAGINGNEW));
    this.addBaseProperty(ISMTelemetryProperties::NUMOFTARGETNEW, int2Str(dmfDefinitionGroupExecutionHistory.NUMOFTARGETNEW));
    this.addBaseProperty(ISMTelemetryProperties::NOOFTHREADS, int2Str(dmfDefinitionGroupExecutionHistory.NOOFTHREADS));
    this.addBaseProperty(ISMTelemetryProperties::SEQUENCE, int2Str(dmfDefinitionGroupExecutionHistory.SEQUENCE));
    this.addBaseProperty(ISMTelemetryProperties::TARGETSTATUS, int2Str(dmfDefinitionGroupExecutionHistory.TARGETSTATUS));
    this.addBaseProperty(ISMTelemetryProperties::STAGINGSTATUS, int2Str(dmfDefinitionGroupExecutionHistory.STAGINGSTATUS));
    this.addBaseProperty(ISMTelemetryProperties::STAGINGERRORCOUNT, int2Str(dmfDefinitionGroupExecutionHistory.STAGINGERRORCOUNT));
    this.addBaseProperty(ISMTelemetryProperties::TARGETERRORCOUNT, int2Str(dmfDefinitionGroupExecutionHistory.TARGETERRORCOUNT));
    this.addBaseProperty(ISMTelemetryProperties::NUMOFTARGETDELETED, int2Str(dmfDefinitionGroupExecutionHistory.NUMOFTARGETDELETED));
    this.addBaseProperty(ISMTelemetryProperties::ERRORFILEID, dmfDefinitionGroupExecutionHistory.ERRORFILEID);
    this.addBaseProperty(ISMTelemetryProperties::CREATEDDATETIME, date2Str(DateTimeUtil::date(dmfDefinitionGroupExecutionHistory.CREATEDDATETIME),1,1,1,1,1,1));

